def summarize(values):
    if not values:
        return {'count': 0, 'total': 0, 'mean': None, 'min': None, 'max': None}
    return {'count': len(values), 'total': sum(values), 'mean': sum(values)/len(values), 'min': min(values), 'max': max(values)}

def test_empty(self):
    self.assertEqual(summarize([]),{'count':0,'total':0,'mean':None,'min':None,'max':None})
def test_negative(self):
    self.assertEqual(summarize([-1,-2,-3]),{'count':3,'total':-6,'mean':-2.0,'min':-3,'max':-1})
def test_immutability(self):
    data=[3,1,2]
    original=list(data)
    summarize(data)
    self.assertEqual(data,original)

